  const cards = "<article id=\"entry-dgp-1086\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱρέσιμος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1086 na letra α · nº geral 1086</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se pode submeter; conquistável. 〈αἱρέω〉</p></section></article>\n<article id=\"entry-dgp-1087\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἵρεσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1087 na letra α · nº geral 1087</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de tomar; tomada; conquista: αἵρεσις δυνάμεως tomada do poder 2 escolha: αἵρεσιν διδόναι ou νέμειν deixar a escolha a alguém, dat.; αἵρεσιν λαμβάνειν ter a escolha, οὐκ ἔχειν αἵρεσιν não admitir escolha 3 escolha por voto; eleição 4 função eletiva; magistratura 5 preferência; inclinação; apego a, πρός e ac. 6 desígnio; intenção 7 estudo específico 8 escola;doutrina filosófica; seita 9 crist. heresia. 〈αἱρέω〉</p></section></article>\n<article id=\"entry-dgp-1088\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱρετέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1088 na letra α · nº geral 1088</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de αἱρέω.</p></section></article>\n<article id=\"entry-dgp-1089\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱρετίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1089 na letra α · nº geral 1089</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ᾑρέτισα, perf. ᾑρέτικα) preferir; aderir a; escolher, ac. ou inf. 〈αἱρετός〉</p></section></article>\n<article id=\"entry-dgp-1090\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱρετικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1090 na letra α · nº geral 1090</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que escolhe; que adere a, gen. 2 crist. que toma partido; sectário 3 crist. que causa divisão; faccioso; herético 4 Astrol. escolhido ou designado para nascer sob uma constelação. 〈αἱρετός〉</p></section></article>\n<article id=\"entry-dgp-1091\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱρετός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1091 na letra α · nº geral 1091</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que pode ser tomado 2 que pode ser apreendido ou compreendido 3 que tem probabilidade de ser escolhido; desejável 4 escolhido; eleito: δικασταὶ αἱρετοί juízes eleitos, αἱρετὴ ἀρχή magistratura eletiva ♦ οἱ αἱρετοί 5 os escolhidos ou eleitos para uma delegação; delegados; comissários. 〈αἱρέω〉</p></section></article>\n<article id=\"entry-dgp-1092\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱρεύμενος</h1><div class=\"entry-meta\"><span>DGP · ordem 1092 na letra α · nº geral 1092</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pres. méd. jôn. de αἱρέω.</p></section></article>\n<article id=\"entry-dgp-1093\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1093 na letra α · nº geral 1093</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ᾕρουν, fut. αἱρήσω, aor.2 εἷλον, perf. ᾕρηκα; pas. fut. αἱρεθήσομαι, aor. ᾑρέθην, perf. ᾕρημαι) ativa 1 pegar; tomar pela força; agarrar 2 capturar; apoderar-se de; vencer 3 prender alguém; surpreender alguém no ato 4 condenar; provar alguma coisa; vencer uma causa 5 conquistar 6 apreender pela razão; compreender média 7 tomar para si 8 escolher; preferir 9 eleger 1 χειρὸς ἑλόντ’ ἀγέμεν hom. tendo[-a] tomado pela mão, conduzi-a, τρίαιναν ἑλὼν χερσὶ στιβαρῇσιν hom. tendo ele agarrado seu tridente com as mãos vigorosas, ἄξω ἑλών hom. tendo[-a] tomado pela força, trarei, i.e., vou trazê-la à força 2 ζωοὺς ἕλον πολλούς hom. capturaram muitos deles vivos, ἡ γὰρ φύσις παραμένουσ’ αἱρεῖ κακά eur. a natureza, mantendo-se firme, vence os males, ἐμὲ χλωρὸν δέος ᾕρει hom. invadia-me um lívido temor 3 φῶρα κλοπῇ ἑλεῖν plat. apanhar um ladrão em flagrante, τήνδ’ εἵλομεν θάπτουσαν eur. nós a surpreendemos enquanto sepultava (o morto) 4 εἷλε σ’ ἡ Δίκη eur. a Justiça te condenou, ἀλλά σε κλέπτονθ’ αἱρήσω ar. mas provarei que roubas, αἱρεῖν δίκην dem. ganhar um processo 5 μεγάλα δ’ ἐπινοεῖς ἑλεῖν eur. grandes prêmios planejas conquistar, αἱρεῖν κῦδος hom. obter a glória 6 εἴπερ ἱκανῶς μέλλομεν τὴν ὑφαντικὴν αἱρήσειν plat. se é que vamos compreender suficientemente a arte do tecelão, ὁ λόγος οὕτω αἰρέει her. a razão assim apreende 7 δόρπον ἕλοντο hom. tomaram a refeição, ὅρκον ἕλωμαι hom. se eu obtivesse um juramento 8 ἀλήτην βίον εἵλευ her. escolheste uma vida errante, τοῖς ἄλλοις τὴν δουλείαν αἱρουμένοις συγγνώμην εἷχον isócr. aos outros, por preferirem a servidão, perdoavam 9 αἱροῦνται αὐτὸν ἄρχοντα τῆς εἰς Μήδους στρατείας xen. elegem-no chefe da expedição contra os medos.</p></section></article>\n<article id=\"entry-dgp-1094\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄϊρος</h1><div class=\"entry-meta\"><span>DGP · ordem 1094 na letra α · nº geral 1094</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">em Ἴρος ἄϊρος hom. Iros que não é Iros, Iros infeliz. 〈ἀ-, Ἴρος〉</p></section></article>\n<article id=\"entry-dgp-1095\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴρω</h1><div class=\"entry-meta\"><span>DGP · ordem 1095 na letra α · nº geral 1095</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ᾖρον, fut. ἀρῶ, aor. ἦρα, perf. ἦρχα; pas. fut. ἀρθήσομαι, aor. ἤρθην, perf. ἦρμαι) ativa 1 levantar; erguer 2 pegar para levar ou trazer; transportar 3 tomar; tirar algo, ac., de, ἀπό e gen.; tomar sobre si; suportar 4 elevar; exaltar; exagerar 5 elevar; fazer crescer 6 levar para fora; fazer desaparecer; expulsar algo, ac., de, ἐκ e gen. 7 lançar ao mar (navio); fazer partir 8 intr. partir média 9 erguer; elevar, tomar 10 tomar nas mãos; empreender; assumir; suportar 11 tomar para si; alcançar; obter 12 fazer desaparecer 1 μύδρους αἴρειν χεροῖν sóf. levantar com as mãos ferros em brasa, αἴρειν μηχανάς plat. erguer a maquinaria (de teatro), ἕως ἂν τὸ τεῖχος ἱκανὸν αἴρωσιν tuc. até que eles ergam um muro que seja suficiente 2 μή μοι οἷνον ἄειρε hom. não me tragas vinho, μῆλα ἄειραν νηυσί hom. transportaram rebanhos nas naus 3 ἄρας τι τῶν ἀπὸ τραπέζης teofr. tendo tomado da mesa uma das iguarias, αἴρειν ὕδωρ ar. tirar água, ἄρατε τὸν ζυγόν μου ἐφ’ ὑμᾶς n.t. tomai o meu jugo sobre vós 4 πολλῷ ἐπαίνῳ ὑψηλὸν ἀρῶ eur. com muito louvor (te) elevarei às alturas, τῷ λόγῳ τὸ πρᾶγμ’ ἐγὼ νῦν αἴρω dem. agora com a palavra exalto a ação, ἐπὶ μείζον τῷ λόγῳ αἴρειν plut. exagerar com a palavra 5 ὄλβον Δαρεῖος ἦρεν ésql. Dario fez crescer a prosperidade, αἴρειν θάρσος eur. tomar coragem 6 τούσδ’ ἱκτῆρας κλάδους ἄρατε sóf. retirai esses ramos suplicantes, αἴρειν ἐκ πόλεως plat. expulsar (alguém) da cidade, αἴρειν τὸν πόλεμον pol. fazer cessar a guerra, αἴρειν τὴν ἁμαρτίαν sept. abolir o pecado 7 τὰς ναῦς ἄραντες tuc. tendo eles lançado as naus ao mar, αἴρειν βουλόμενος καὶ πλεῖν ἐπὶ τὸν Ἰσθμόν plut. querendo levantar âncora e navegar para o istmo de Corinto 8 αἴρειν τῷ στράτῳ tuc. partir com o exército 9 αἴρεσθαι τὰ ἱστία plut. içar as velas, αἴρεσθαι φορτίον dem. erguer um fardo, αἴρεσθαι φωνήν ar. elevar a voz 10 πρεσβύτερός τε ἤδη εἰμὶ καὶ βαρὺς ἀείρεσθαι her. já sou muito velho e lento para tomar iniciativa, ἄρασθαι πόλεμον ésql. empreender uma guerra, κίνδυνον ἀράμενος ant. tendo ele assumido o perigo, ἐκείνῳ δυσμένειαν ἠράμην eur. enfrentei sua inimizade 11 αἴρεσθαι νίκας, κλέος, κῦδος, alcançar vitórias, glória, renome 12 αἴρεσθαι πόλιν d.h. destruir uma cidade.</p></section></article>\n<article id=\"entry-dgp-1096\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἄϊς</h1><div class=\"entry-meta\"><span>DGP · ordem 1096 na letra α · nº geral 1096</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só gen. Ἄϊδος, dat. Ἄϊδι, ac. Ἄϊδα) = Ἀΐδης.</p></section></article>\n<article id=\"entry-dgp-1097\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἷσα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1097 na letra α · nº geral 1097</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 parte; porção: αἷσα χθονός pínd. porção de terra 2 parte destinada a cada um; quinhão; destino: αἷσά μοι ἐστί hom. é meu destino, inf. 3 medida; regra; conveniência: κατ’ αἷσαν, ἐν αἷσᾳ como convém; παρὰ ou ὑπὲρ αἷσαν hom. além do conveniente 4 decreto; decisão de um deus: Διὸς ὑπὲρ αἷσαν hom. contra a vontade de Zeus 5 Αἷσα person. Esa, o Destino.</p></section></article>\n<article id=\"entry-dgp-1098\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσθάνομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1098 na letra α · nº geral 1098</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ᾐσθανόμην, fut. αἰσθήσομαι, aor.2 ᾐσθόμην, perf. ᾔσθημαι) 1 perceber pelos sentidos ou pela mente; ouvir; ver; sentir; perceber, gen. ou ac., com part. predic. do suj., com ac. ou gen. e part., com ὅτι: ὥς μοι πολλὰς μὲν θρήνων ᾠδάς, πολλὰς δ’ ᾔσθου πλαγάς sóf. quantos cantos de dor (ouviste) de mim, tantos golpes me (viste dar), ᾔσθησαί μου ψευδομαρτυροῦντος; xen. percebeste que eu dava falso testemunho? 2 ser inteligente; ter consciência de si; estar em plena posse das faculdades: ἐπεβίων δὲ παντὸς αὐτοῦ αἰσθόμενός τε τῇ ἡλικίᾳ tuc. vivi-a [a guerra] inteira, pela idade que tinha, em plena posse de minhas faculdades. 〈ἀΐω〉</p></section></article>\n<article id=\"entry-dgp-1099\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄϊσθε</h1><div class=\"entry-meta\"><span>DGP · ordem 1099 na letra α · nº geral 1099</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a. sing. impf. poét. de ἀΐσθω.</p></section></article>\n<article id=\"entry-dgp-1100\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴσθημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1100 na letra α · nº geral 1100</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 o sentir, sensação 2 o objeto de sen­sação, o sentido. 〈αἰσθάναομαι〉</p></section></article>\n<article id=\"entry-dgp-1101\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴσθησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1101 na letra α · nº geral 1101</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 percepção pelos sentidos; faculdade de sentir: πᾶσαν αἴσθησιν αἰσθάνεσθαι plat. experimentar toda e qualquer sensação 2 percepção pela inteligência; noção; conhecimento: αἴσθησιν λαμβάνειν, ἔχειν ter a sensação, a percepção de algo, gen., αἴσθησιν παρέχειν, ποιεῖν fazer ver, fazer compreender a alguém, gen. 3 órgão dos sentidos 4 pl. os sentidos 5 rasto; pista. 〈αἰσθάνομαι〉</p></section></article>\n<article id=\"entry-dgp-1102\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσθήσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1102 na letra α · nº geral 1102</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de αἰσθάνομαι.</p></section></article>\n<article id=\"entry-dgp-1103\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσθητήριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1103 na letra α · nº geral 1103</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 órgão dos sentidos 2 bíbl. pl. sentidos, faculdades, poder de discernimento. 〈αἰσθάνομαι〉</p></section></article>\n<article id=\"entry-dgp-1104\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσθητικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1104 na letra α · nº geral 1104</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 capaz de perceber algo, gen.: ἡ αἰσ­θητικὴ δύναμις a faculdade de sentir 2 apreensível pelos sentidos; sensível. 〈αἰσθητός〉</p></section></article>\n<article id=\"entry-dgp-1105\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσθητικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1105 na letra α · nº geral 1105</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. sensivelmente. 〈αἰσθάνομαι〉</p></section></article>\n<article id=\"entry-dgp-1106\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσθητός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1106 na letra α · nº geral 1106</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sensível; perceptível. 〈αἰσθάνομαι〉</p></section></article>\n<article id=\"entry-dgp-1107\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσθητῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1107 na letra α · nº geral 1107</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de maneira sensível; sensivelmente.</p></section></article>\n<article id=\"entry-dgp-1108\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴσθομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1108 na letra α · nº geral 1108</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) = αἰσθάνομαι.</p></section></article>\n<article id=\"entry-dgp-1109\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αΐσθω</h1><div class=\"entry-meta\"><span>DGP · ordem 1109 na letra α · nº geral 1109</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só part. pres. ἀΐσθων e 3ª sing. impf. ép. ἄισθε) exalar, soprar: αὐτὰρ ὁ θυμὸν αἴσθε hom. então exalou seu sopro de vida.</p></section></article>\n<article id=\"entry-dgp-1110\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσιμία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1110 na letra α · nº geral 1110</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">duv. proveito; fruição ou repartição justa. 〈αἴσιμος〉</p></section></article>\n<article id=\"entry-dgp-1111\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴσιμος, ος</h1><div class=\"entry-meta\"><span>DGP · ordem 1111 na letra α · nº geral 1111</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e η, ον 1 fixado pelo destino; fatal: αἴσιμόν ἐστι hom. é fatal 2 conforme a norma, conveniente; justo: αἴσιμα εἰδώς hom. de espírito prudente, αἴσιμα εἰπεῖν hom. dizer coisas adequadas, πρὶν δὲ φρένας αἰσίμη ἦσθα hom. outrora eras bem equilibrada de sentimentos ♦ αἴσιμα adv. 4 com medida, com moderação. 〈αἷσα〉</p></section></article>\n<article id=\"entry-dgp-1112\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσιόομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1112 na letra α · nº geral 1112</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">considerar de bom augúrio. 〈αἴσιος〉</p></section></article>\n<article id=\"entry-dgp-1113\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴσιος, ος</h1><div class=\"entry-meta\"><span>DGP · ordem 1113 na letra α · nº geral 1113</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e α, ον 1 oportuno; favorável 2 que acontece segundo a regra; conveniente; justo. 〈αἷσα〉</p></section></article>\n<article id=\"entry-dgp-1114\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀΐσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1114 na letra α · nº geral 1114</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">at. ᾄσσω, ᾄττω e ἄττω (impf. ἤϊσσον e ᾖσσον; fut. ἀΐξω e ᾄξω; aor.ἤϊξα e ᾖξα; perf. desus.; pas. aor. ἠΐχθην) 1 mover-se rapidamente; lançar-se; saltar: ἀ. ἔγχεϊ hom. precipitar-se para frente com a lança, δούρατα ἐκ χειρῶν ἤϊξαν hom. as lanças saltaram de suas mãos 2 precipitar-se em; esforçar-se para, inf. ou εἰς e ac.: οὐδ’ ᾖξας εἰς ἔρευναν ἐξευρεῖν γονάς; eur. não te apressaste na busca para achar teus pais? 3 (pres. e aor.) mover rapidamente; agitar: ἀ. χέρα sóf. mover a mão, διά μου κεφαλῆς ᾄσσουσ’ ὀδύναι eur. pela minha cabeça agitam-se dores ♦ méd. 4 precipitar-se; agitar-se: πυλάων ἀντίον ἀΐζασθαι hom. lançar-se contra as portas, κόμη δι᾽ αὔρας ᾄσσεται sóf. os cabelos agitam-se ao vento.</p></section></article>\n<article id=\"entry-dgp-1115\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄϊστος,</h1><div class=\"entry-meta\"><span>DGP · ordem 1115 na letra α · nº geral 1115</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contr. αἶστος, ος, ον 1 não visto; invisível; desaparecido 2 desconhecido; obscuro 3 que não vê; que não conhece, gen. 〈ἀ-, ἰδεῖν〉</p></section></article>\n<article id=\"entry-dgp-1116\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀϊστόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1116 na letra α · nº geral 1116</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἀϊστώσω, aor. ἠΐστωσα e ᾔστωσα, perf. desus.; pas. aor. ép. 3ª pl. ἀϊστώθησαν) 1 tornar invisível; fazer desaparecer; destruir ♦ pas. 2 aor. desaparecer. 〈ἄϊστος〉</p></section></article>\n<article id=\"entry-dgp-1117\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσυλοεργός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1117 na letra α · nº geral 1117</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que pratica atos ímpios; malvado. 〈αἴσυλος, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-1118\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴσυλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1118 na letra α · nº geral 1118</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ímpio; inconveniente; mau.</p></section></article>\n<article id=\"entry-dgp-1119\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰσύμηθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1119 na letra α · nº geral 1119</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de Esima, cidade da Trácia.</p></section></article>\n<article id=\"entry-dgp-1120\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσυμνάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1120 na letra α · nº geral 1120</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) dirigir; governar, gen. 〈αἷσα〉</p></section></article>\n<article id=\"entry-dgp-1121\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσυμνήτηρ, ῆρος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1121 na letra α · nº geral 1121</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">governador; príncipe.</p></section></article>\n<article id=\"entry-dgp-1122\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσυμνήτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1122 na letra α · nº geral 1122</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">organizador de jogos; supervisor; árbitro.</p></section></article>\n<article id=\"entry-dgp-1123\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰσχίνης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1123 na letra α · nº geral 1123</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Ésquines, orador ateniense, rival de Demóstenes.</p></section></article>\n<article id=\"entry-dgp-1124\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴσχιστος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1124 na letra α · nº geral 1124</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">superl. de αἰσχρός.</p></section></article>\n<article id=\"entry-dgp-1125\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχίων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1125 na letra α · nº geral 1125</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος comp. de αἰσχρός.</p></section></article>\n<article id=\"entry-dgp-1126\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἷσχος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1126 na letra α · nº geral 1126</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 opróbrio; vergonha; infâmia 2 pl. atos ou palavras vergonhosas 3 deformidade física; feiúra.</p></section></article>\n<article id=\"entry-dgp-1127\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχροκέρδεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1127 na letra α · nº geral 1127</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ganância; cupidez. 〈αἰσχροκερδής〉</p></section></article>\n<article id=\"entry-dgp-1128\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχροκερδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1128 na letra α · nº geral 1128</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ávido de ganho; cúpido; avaro. 〈αἰσχρός, κέρδος〉</p></section></article>\n<article id=\"entry-dgp-1129\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχροκερδῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1129 na letra α · nº geral 1129</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com ganância; com ambição sórdida.</p></section></article>\n<article id=\"entry-dgp-1130\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχρολογία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1130 na letra α · nº geral 1130</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fala indecente; obscenidade. 〈αἰσχρός, λόγος〉</p></section></article>\n<article id=\"entry-dgp-1131\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχρόμητις, ιος</h1><div class=\"entry-meta\"><span>DGP · ordem 1131 na letra α · nº geral 1131</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) que dá maus conselhos. 〈αἰσχρός, μῆτις〉</p></section></article>\n<article id=\"entry-dgp-1132\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχροποιός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1132 na letra α · nº geral 1132</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que comete atos infames; que se comporta vergonhosamente. 〈αἰσχρός, ποιέω〉</p></section></article>\n<article id=\"entry-dgp-1133\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1133 na letra α · nº geral 1133</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(comp. αἰσχίων, superl. αἴσχιστος) 1 objeto de opróbrio; vil; indigno (pessoas) 2 incapaz (animais); indigno; infame (coisas); feio; medonho (pessoas e coisas); funesto; lastimável 3 inconveniente; impróprio para algo, πρός e ac. 4 desonroso; infamante: αἰσχρόν ἐστι é vergonhoso, inf. ♦ τὸ αἰσχρόν 5 vergonha; τὸ καλὸν καὶ τὸ αἰσχρόν o bem e o mal ou a virtude e o vício (para os estóicos).</p></section></article>\n<article id=\"entry-dgp-1134\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχρότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1134 na letra α · nº geral 1134</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 feiúra; deformidade 2 bíbl. comportamento indecente. 〈αἰσχρός〉</p></section></article>\n<article id=\"entry-dgp-1135\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχρουργία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1135 na letra α · nº geral 1135</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 conduta vergonhosa 2 obscenidade. 〈αἰσχρός, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-1136\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχρῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1136 na letra α · nº geral 1136</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. vergonhosamente.</p></section></article>\n<article id=\"entry-dgp-1137\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχυνέμεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1137 na letra α · nº geral 1137</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. pres. ép. de αἰσχύνω.</p></section></article>\n<article id=\"entry-dgp-1138\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχυνέω</h1><div class=\"entry-meta\"><span>DGP · ordem 1138 na letra α · nº geral 1138</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. jôn. de αἰσχύνω.</p></section></article>\n<article id=\"entry-dgp-1139\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχύνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1139 na letra α · nº geral 1139</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 causa de vergonha; injúria, opróbrio: αἰσχύνην ἔχειν, φέρειν, προσβάλλειν causar desonra a alguém, dat., γράφεσθαί τινα γένους αἰσχύνης plat. acusar alguém de ação desonrosa contra a estirpe 2 situação vergonhosa; desonra: αἰσχύνη συμβᾶσα τῇ πόλει dem. vergonha que aconteceu à cidade, αἰσχύνῃ πίπτειν sóf. cair em desonra 3 sentimento de vergonha; comedimento; respeito; αἰσχύνην ἔχειν ter vergonha de, gen., πᾶσαν αἰσχύνην ἀφιέναι dem. perder toda a vergonha, αἰσχύνῃ ἠφείδουν σφῶν αὐτῶν tuc. por brio não se poupavam, αἰσχύνην ὁμολογουμένην φέρουσι tuc. [leis não escritas] que gozam de respeito unânime 4 ultraje ao pudor; estupro. 〈αἷσχος〉</p></section></article>\n<article id=\"entry-dgp-1140\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχυνοῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1140 na letra α · nº geral 1140</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. méd. pas. de αἰσχύνω.</p></section></article>\n<article id=\"entry-dgp-1141\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχυντέον</h1><div class=\"entry-meta\"><span>DGP · ordem 1141 na letra α · nº geral 1141</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de αἰσχύνω.</p></section></article>\n<article id=\"entry-dgp-1142\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχυντηλία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1142 na letra α · nº geral 1142</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pudor; modéstia.</p></section></article>\n<article id=\"entry-dgp-1143\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχυντηλός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1143 na letra α · nº geral 1143</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pudico; modesto 2 que causa vergonha ♦ τὸ αἰσχυντηλόν 3 modéstia; pudor. 〈αἰσχύνω〉</p></section></article>\n<article id=\"entry-dgp-1144\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχυντήρ, ῆρος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1144 na letra α · nº geral 1144</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">homem que desonra; adúltero. 〈αἰσχύνω〉</p></section></article>\n<article id=\"entry-dgp-1145\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχυντικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1145 na letra α · nº geral 1145</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que causa vergonha.</p></section></article>\n<article id=\"entry-dgp-1146\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1146 na letra α · nº geral 1146</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ᾔσχυνον, fut. αἰσχυνῶ, aor. ᾔσχυνα, perf. rec. ᾔσχυγκα) 1 tornar feio: χαριὲν δ’ ᾔσχυνε πρόσωπον hom. desfigurava seu belo rosto, κόμην ᾔσχυνε δαΐζων hom. enfeava a cabeleira arrancando os cabelos 2 ultrajar; profanar; estuprar: αἰσχύνεις πόλιν sóf. desonras a cidade, ᾔσχυνε ξενίαν τράπεζαν ésql. ultrajou a mesa hospitaleira, [εἴ τινες] τούς τε παῖδας καὶ τὰς γυναῖκας αἰσχύνοειν isócr. se algumas pessoas estuprassem mulheres e crianças 3 desacreditar: ᾔσχυνας μὲν ἐμὴν ἀρετήν hom. denegriste meu valor ♦ méd. 4 ter vergonha de algo, ac., dat., ἐν ou ἐπί e dat., ὑπέρ e gen.: αἰσχυνόμενος τῇ συμφορᾷ lís. envergonhado com o acontecimento; envergonhar-se de fazer algo, part.: αἰσχύνω ποιῶν tenho vergonha de fazer (mas faço), οὐκ ἂν αἰσχύνοιό σε παρέχων σοφιστήν; plat. tu não te envergonharias de te apresentares como sofista? com inf. ou or. com εἰ, ἤν, μή: αἰσχύνω ποιεῖν tenho vergonha de fazer (e não faço) 5 corar diante de alguém, ac. ou πρός e ac. 〈αἰσχύνη〉</p></section></article>\n<article id=\"entry-dgp-1147\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἴσωπος, ου (ὀ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1147 na letra α · nº geral 1147</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Esopo, n. de fabulista e de ator trágico.</p></section></article>\n<article id=\"entry-dgp-1148\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴτε</h1><div class=\"entry-meta\"><span>DGP · ordem 1148 na letra α · nº geral 1148</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = εἴτε.</p></section></article>\n<article id=\"entry-dgp-1149\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰτεύμενος</h1><div class=\"entry-meta\"><span>DGP · ordem 1149 na letra α · nº geral 1149</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pres. pas. jôn. de αἰτέω.</p></section></article>\n<article id=\"entry-dgp-1150\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1150 na letra α · nº geral 1150</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ᾔτουν, fut. αἰτήσω, aor. ᾔτησα, perf. ᾔτηκα; pas. fut. αἰτηθήσομαι, aor. ᾐτήθην, perf. ᾔτημαι) 1 pedir; solicitar; postular a alguém, ac. ou πρός, παρά e gen.; algo, ac. ou or. inf. ou conj. (ὅπως); em benefício de alguém, dat. ♦ méd. 2 pedir para si; implorar; reclamar (com as mesmas construções da at.) ♦ pas. 3 ser solicitado: αἰτηθέντες χρήματα her. solicitados a dar seus bens, αἰτεύμενος teócr. solicitado a fazer algo, inf.; ἵπποι ᾐτημένοι lís. cavalos tomados de empréstimo; τὸ αἰτεόμενον her. aquilo que se pede.</p></section></article>\n<article id=\"entry-dgp-1151\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴτημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1151 na letra α · nº geral 1151</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pedido; petição 2 princípio de demonstração; postulado. 〈αἰτέω〉</p></section></article>\n<article id=\"entry-dgp-1152\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰτηματώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 1152 na letra α · nº geral 1152</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem o caráter de hipótese. 〈αἴτημα〉</p></section></article>\n<article id=\"entry-dgp-1153\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴτησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1153 na letra α · nº geral 1153</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pedido; súplica 2 postulado. 〈αἰτέω〉</p></section></article>\n<article id=\"entry-dgp-1154\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰτητικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1154 na letra α · nº geral 1154</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que gosta de pedir 2 que pode ser pedido; desejável. 〈αἰτέω〉</p></section></article>\n<article id=\"entry-dgp-1155\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰτητός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1155 na letra α · nº geral 1155</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">solicitado; desejável. 〈αἰτέω〉</p></section></article>\n<article id=\"entry-dgp-1156\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰτία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1156 na letra α · nº geral 1156</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 princípio; origem: αἱ πρῶται αἰτίαι plat. as causas primeiras 2 razão: δι’ ἣν αἰτίαν ἐπολέμησαν her. motivo pelo qual fizeram a guerra 3 responsabilidade: αἰτία θεοῦ ésql. a responsabilidade do deus, τὴν αἰτίαν ἐνδέχεσθαι tomar a responsabilidade, τὴν αἰτίαν εἰς αὑτὸν φέρειν assumir a responsabilidade, αἰτίαν ἀνατιθέναι, ἐπιτιθέναι, ἐπιφέρειν atribuir a responsabilidade a alguém, dat. 4 acusação: ἀφιέναι τινὰ τῆς αἰτίας lís. absolver alguém de uma acusação, αἰτίαν ἔχειν, ὑπέχειν, ὑπομένειν, φέρεσθαι ou εἰς αἰτίαν ἐλθεῖν, ἐμπίπτειν ou αἰτίας τυγχάνειν ou ἐν αἰτίᾳ εἷναι, γίγνεσθαι ser acusado, sofrer uma acusação, estar sob acusação 5 eufór. reputação: αἰτίαν ἔχουσι βελτίους γεγονέναι plat. têm a reputação de se terem tornado melhores 6 bíbl. condição; situação: εἰ οὕτως ἐστὶν ἡ αἰτία τοῦ ἀνθρώπου μετὰ τῆς γυναικός, οὐ συμφέρει γαμῆσαι n.t. se tal é a condição do homem em relação à mulher, não convém casar. 〈αἴτιος〉</p></section></article>\n<article id=\"entry-dgp-1157\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰτιάζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1157 na letra α · nº geral 1157</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ᾐτιαζόμην) ser acusado de algo, gen. 〈αἰτία〉</p></section></article>\n<article id=\"entry-dgp-1158\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰτίαμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1158 na letra α · nº geral 1158</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">acusação; motivo de queixa; culpa. 〈αἰτιάομαι〉</p></section></article>\n<article id=\"entry-dgp-1159\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰτιάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1159 na letra α · nº geral 1159</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. αἰτιάσομαι, aor. ᾐτιασάμην, perf. ᾐτίαμαι) 1 ver como causa: οὐ τὸ αἴτιον αἰτιᾶσθαι plat. não considerar como causa o que é a causa 2 apresentar como causa; pretextar: τὸν λόγον αἰτιᾶσθαι δυσχερῆ εἷναι plat. alegar que o raciocínio é difícil 3 pôr em discussão; acusar: οἷον θεοὺς βροτοὶ αἰτιόωνται hom. como os mortais acusam os deuses! αἰτιᾶσθαί τινα ποιεῖν τι her. acusar alguém de fazer algo, αἰτίαν κατά τινος αἰτιᾶσθαι ant. fazer uma acusação contra alguém 4 rar. louvar: σὲ τίς αἰτιᾶται νομοθέτην ἀγαθὸν γεγονέναι; plat. quem te louva por teres sido um bom legislador? 〈αἰτία〉</p></section></article>\n<article id=\"entry-dgp-1160\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰτιατέον</h1><div class=\"entry-meta\"><span>DGP · ordem 1160 na letra α · nº geral 1160</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de αἰτιάομαι.</p></section></article>\n<article id=\"entry-dgp-1161\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰτίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1161 na letra α · nº geral 1161</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e part. aor. poét. αἰτίσσας) pedir com insistência; mendigar algo, ac., a alguém, dat. 〈αἰτέω〉</p></section></article>\n<article id=\"entry-dgp-1162\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰτιολογέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1162 na letra α · nº geral 1162</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">argumentar sobre as causas. 〈αἰτία, λόγος〉</p></section></article>\n<article id=\"entry-dgp-1163\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴτιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1163 na letra α · nº geral 1163</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que é causa de, gen. 2 responsável; culpado; acusado de, gen. ♦ ὁ αἴτιος 3 o acusado ♦ τὸ αἴτιον 4 causa; razão; motivo: τοῦτο αἴτιον ὅτι isso é causa de que. 〈αἰτία〉</p></section></article>\n<article id=\"entry-dgp-1164\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰτίωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1164 na letra α · nº geral 1164</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. = αἰτίαμα.</p></section></article>\n<article id=\"entry-dgp-1165\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰτιόωνται</h1><div class=\"entry-meta\"><span>DGP · ordem 1165 na letra α · nº geral 1165</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e αἰτιόωντο 3ª pl. pres. e impf. ép. de αἰ­τιάομαι.</p></section></article>\n<article id=\"entry-dgp-1166\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰτιόῳο</h1><div class=\"entry-meta\"><span>DGP · ordem 1166 na letra α · nº geral 1166</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e αἰτιόῳτο 2ª e 3ª sing. opt. ép. de αἰτιάομαι.</p></section></article>\n<article id=\"entry-dgp-1167\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰτναῖος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1167 na letra α · nº geral 1167</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">etneu, peixe do mar.</p></section></article>\n<article id=\"entry-dgp-1168\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰτναῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1168 na letra α · nº geral 1168</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 do Etna 2 grande como o Etna; gigantesco 3 da região do Etna. 〈Αἴτνη〉</p></section></article>\n<article id=\"entry-dgp-1169\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἴτνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1169 na letra α · nº geral 1169</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Etna, monte, vulcão e cidade da Sicília .</p></section></article>\n<article id=\"entry-dgp-1170\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰτωλία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1170 na letra α · nº geral 1170</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Etólia, região da Grécia.</p></section></article>\n<article id=\"entry-dgp-1171\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰτωλικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1171 na letra α · nº geral 1171</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">etólio. 〈Αἰτωλία〉</p></section></article>\n<article id=\"entry-dgp-1172\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰτωλίς, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 1172 na letra α · nº geral 1172</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) etólia. 〈Αἰτωλία〉</p></section></article>\n<article id=\"entry-dgp-1173\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰτωλός, οῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 1173 na letra α · nº geral 1173</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) etólio. 〈Αἰτωλία〉</p></section></article>\n<article id=\"entry-dgp-1174\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴφνης</h1><div class=\"entry-meta\"><span>DGP · ordem 1174 na letra α · nº geral 1174</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. subitamente; de repente.</p></section></article>\n<article id=\"entry-dgp-1175\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰφνίδιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1175 na letra α · nº geral 1175</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 repentino; súbito; imprevisto ♦ αἰφνίδιον adv. 2 subitamente; de repente ♦ τὸ αἰφνίδιον 3 o imprevisto. 〈αἴφνης〉</p></section></article>\n<article id=\"entry-dgp-1176\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰφνιδίως</h1><div class=\"entry-meta\"><span>DGP · ordem 1176 na letra α · nº geral 1176</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. subitamente; de repente.</p></section></article>\n<article id=\"entry-dgp-1177\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀΐχθην</h1><div class=\"entry-meta\"><span>DGP · ordem 1177 na letra α · nº geral 1177</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. pas. de ἀΐσσω.</p></section></article>\n<article id=\"entry-dgp-1178\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰχμά</h1><div class=\"entry-meta\"><span>DGP · ordem 1178 na letra α · nº geral 1178</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = αἰχμή.</p></section></article>\n<article id=\"entry-dgp-1179\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰχμάεις</h1><div class=\"entry-meta\"><span>DGP · ordem 1179 na letra α · nº geral 1179</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = αἰχμήεις.</p></section></article>\n<article id=\"entry-dgp-1180\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰχμάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1180 na letra α · nº geral 1180</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. αἰχμάσω, aor. ᾔχμασα) 1 brandir ou arremessar a lança 2 ferir. 〈αἰχμή〉</p></section></article>\n<article id=\"entry-dgp-1181\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰχμαλωσία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1181 na letra α · nº geral 1181</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cativeiro de guerra; cativeiro 2 grupo de cativos de guerra. 〈αἰχμάλωτος〉</p></section></article>\n<article id=\"entry-dgp-1182\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰχμαλωτεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1182 na letra α · nº geral 1182</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. = αἰχμαλωτίζω.</p></section></article>\n<article id=\"entry-dgp-1183\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰχμαλωτίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1183 na letra α · nº geral 1183</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tornar prisioneiro de guerra 2 escravizar; subjugar: ἕτερον νόμον αἰχμαλωτίζοντά με ἐν τῷ νόμῳ τῆς ἁμαρτίας n.t. outra lei que me torna escravo da lei do pecado 3 cativar; seduzir: οἱ αἰχμαλωτίζοντες γυναικάρια σεσωρευμένα ἁμαρτίας n.t. os que seduzem mulherzinhas sobrecarregadas de pecados. 〈αἰχμάλωτος〉</p></section></article>\n<article id=\"entry-dgp-1184\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰχμαλωτίς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 1184 na letra α · nº geral 1184</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) prisioneira de guerra; cativa. 〈αἰχμάλωτος〉</p></section></article>\n<article id=\"entry-dgp-1185\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰχμάλωτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1185 na letra α · nº geral 1185</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 apreendido na guerra: αἰχμάλωτα χρήματα bens apresados na guerra 2 de prisioneiro de guerra: αἰχ. δουλοσύνη servidão reservada aos prisioneiros, αἰχ. εὐνά leito reservado à mulher prisioneira ♦ οἱ αἰχμάλωτοι 3 prisioneiros de guerra; cativos ♦ τὰ αἰχμάλωτα 4 despojos de guerra. 〈αἰχμή, ἁλίσκομαι〉</p></section></article>\n";
  d.rowsHtml = rowBase.slice(0, rowStart) + rows + rowBase.slice(rowStart);
  d.cardsHtml = cardBase.slice(0, cardStart) + cards + cardBase.slice(cardStart);
